// The payload back out of its jsonb wrapper, so the pipeline receives the
// item exactly as it arrived the first time -- not a copy with replay
// bookkeeping glued to it.
//
// The replay metadata is kept on a single underscored key rather than spread
// across the item, so nothing downstream can start depending on it by
// accident. It is there for the run record, and for the person reading the
// execution afterwards.
return $input.all().map((item) => ({
  json: {
    ...item.json.payload,
    _replay: {
      dead_letter_id: item.json.dead_letter_id,
      original_error: item.json.original_error,
      replayed_by_execution: $execution.id,
    },
  },
}));
